USE QLPHONGKHAM; IF COL_LENGTH(N'dbo.HoSoBenhAn', N'chiDinhCanLamSang') IS NULL ALTER TABLE dbo.HoSoBenhAn ADD chiDinhCanLamSang NVARCHAR(MAX) NULL; IF COL_LENGTH(N'dbo.HoSoBenhAn', N'maLichHenTaiKham') IS NULL ALTER TABLE dbo.HoSoBenhAn ADD maLichHenTaiKham VARCHAR(30) NULL; SELECT COL_LENGTH(N'dbo.HoSoBenhAn', N'chiDinhCanLamSang') AS ChiDinhCanLamSang, COL_LENGTH(N'dbo.HoSoBenhAn', N'maLichHenTaiKham') AS MaLichHenTaiKham; SELECT i.name, i.is_primary_key, i.is_unique FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.object_id=OBJECT_ID(N'dbo.LichHen') AND c.name=N'maLichHen';